export type microsoftTeamsIntegrationLogicType = MakeLogicType<
    microsoftTeamsIntegrationLogicValues,
    microsoftTeamsIntegrationLogicActions,
    microsoftTeamsIntegrationLogicProps,
    microsoftTeamsIntegrationLogicMeta
>

export const microsoftTeamsIntegrationLogic = kea<microsoftTeamsIntegrationLogicType>([
    props({} as { id: number }),
    key((props) => props.id),
    path((key) => ['lib', 'integrations', 'microsoftTeamsIntegrationLogic', key]),
    actions({
        loadMicrosoftTeamsTeams: () => ({}),
        loadMicrosoftTeamsChannels: (teamId: string) => ({ teamId }),
    }),

    loaders(({ props }) => ({
        microsoftTeamsTeams: [
            null as MicrosoftTeamsTeamApi[] | null,
            {
                loadMicrosoftTeamsTeams: async () => {
                    const res = await integrationsMicrosoftTeamsTeamsRetrieve(
                        String(ApiConfig.getCurrentTeamId()),
                        props.id
                    )
                    return res.teams
                },
            },
        ],
        microsoftTeamsChannels: [
            null as MicrosoftTeamsChannelApi[] | null,
            {
                loadMicrosoftTeamsChannels: async ({ teamId }) => {
                    const res = await integrationsMicrosoftTeamsChannelsRetrieve(
                        String(ApiConfig.getCurrentTeamId()),
                        props.id,
                        { team_id: teamId }
                    )
                    return res.channels
                },
            },
        ],
    })),
])
